const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
$('#total').textContent=`${ATLAS.datasets.length} 项`;
function render(){const q=$('#query').value.trim().toLowerCase(),g=$('#group').value,zh=$('#chinese').checked,rec=$('#recommended').checked;const items=ATLAS.datasets.filter(d=>(!q||JSON.stringify(d).toLowerCase().includes(q))&&(!g||d.group===g)&&(!zh||d.language.includes('中文'))&&(!rec||d.priority));$('#count').textContent=`显示 ${items.length} / ${ATLAS.datasets.length} 项`;$('#cards').innerHTML=items.length?items.map(d=>`<details><summary><b>${esc(d.name)}</b><span class="tag">${esc(d.group)} · ${esc(d.language)}${d.priority?' · 优先看':''}</span><small>${esc(d.scale)} — ${esc(d.fit)}</small></summary><div class="detail"><dl>${[['有哪些信息',d.material],['怎么测试',d.evaluation],['怎么用',d.fit],['注意限制',d.limitation],['获取状态',d.access],['自编示意',d.example]].map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v)}</dd>`).join('')}</dl><a href="${esc(d.source)}" target="_blank" rel="noopener">官方资料 / 数据入口 ↗</a></div></details>`).join(''):'<p>没有匹配项，试试清除筛选。</p>'}
['#query','#group','#chinese','#recommended'].forEach(s=>$(s).addEventListener('input',render));$('#reset').onclick=()=>{$('#query').value='';$('#group').value='';$('#chinese').checked=false;$('#recommended').checked=false;render()};render();
$('#caseSelect').innerHTML=ATLAS.cases.map((c,i)=>`<option value="${i}">${esc(c.id)} · ${esc(c.user_affect)} · ${esc(c.domain)}</option>`).join('');
function renderCase(){const c=ATLAS.cases[Number($('#caseSelect').value)];$('#caseDetail').innerHTML=`<h3>${esc(c.id)}：${esc(c.user_affect)} / ${esc(c.domain)}</h3><p class="muted">原创文字草案 · 未录音、未人工验证 · 不依赖声音线索</p>${c.history.length?'<p><b>历史：</b>'+c.history.map(t=>esc(t.role==='user'?'用户：':'助手：')+esc(t.text)).join('<br>')+'</p>':''}<blockquote><b>本轮用户：</b>${esc(c.input_text)}</blockquote><p><b>支持目标：</b>${esc(c.support_goal)}</p><p><b>内容锚点：</b>${esc(c.content_anchors.join('；'))}</p><p><b>可接受声音：</b>${esc(c.acceptable_output_styles.join('、'))}</p><p><b>应避免：</b>${esc(c.failure_examples.join('；'))}</p><blockquote><b>一个可行回复：</b>${esc(c.reference_response_text)}</blockquote><details><summary>查看完整 JSON 字段</summary><pre>${esc(JSON.stringify(c,null,2))}</pre></details>`}$('#caseSelect').onchange=renderCase;renderCase();
